create table public.arteflow_financial_receivables (
 id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id), order_id uuid,
 order_number text, customer_id text, customer_name text not null, description text not null, amount_cents bigint not null check(amount_cents between 1 and 9007199254740991),
 paid_amount_cents bigint not null default 0 check(paid_amount_cents>=0 and paid_amount_cents<=amount_cents), due_date date not null,
 status text not null default 'OPEN' check(status in('OPEN','PARTIALLY_PAID','PAID','CANCELED')), version integer not null default 1 check(version>0),
 created_by uuid not null references auth.users(id), created_at timestamptz not null default now(), updated_at timestamptz not null default now(),
 unique(organization_id,id), unique(organization_id,order_id), foreign key(organization_id,order_id) references public.arteflow_orders(organization_id,id)
);
create table public.arteflow_financial_payables (
 id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id), purchase_order_id uuid,
 purchase_order_number text, supplier_id uuid, supplier_name text not null, description text not null, amount_cents bigint not null check(amount_cents between 1 and 9007199254740991),
 paid_amount_cents bigint not null default 0 check(paid_amount_cents>=0 and paid_amount_cents<=amount_cents), due_date date not null,
 status text not null default 'OPEN' check(status in('OPEN','PARTIALLY_PAID','PAID','CANCELED')), version integer not null default 1 check(version>0),
 created_by uuid not null references auth.users(id), created_at timestamptz not null default now(), updated_at timestamptz not null default now(),
 unique(organization_id,id), unique(organization_id,purchase_order_id),
 foreign key(organization_id,purchase_order_id) references public.arteflow_purchase_orders(organization_id,id),
 foreign key(organization_id,supplier_id) references public.arteflow_suppliers(organization_id,id)
);
create table public.arteflow_financial_settlements (
 id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id), receivable_id uuid, payable_id uuid,
 amount_cents bigint not null check(amount_cents between 1 and 9007199254740991), settled_at timestamptz not null, method text not null check(method in('PIX','TRANSFER','CASH','CARD','OTHER')),
 notes text, idempotency_key text not null, created_by uuid not null references auth.users(id), actor_name text not null, created_at timestamptz not null default now(),
 check((receivable_id is null)<>(payable_id is null)), unique(organization_id,id), unique(organization_id,idempotency_key),
 foreign key(organization_id,receivable_id) references public.arteflow_financial_receivables(organization_id,id),
 foreign key(organization_id,payable_id) references public.arteflow_financial_payables(organization_id,id)
);
create table public.arteflow_financial_events (
 id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id), entity_type text not null check(entity_type in('RECEIVABLE','PAYABLE','SETTLEMENT')),
 entity_id uuid not null, event_type text not null check(event_type in('RECEIVABLE_CREATED','PAYABLE_CREATED','SETTLEMENT_CREATED','PARTIAL_SETTLEMENT','TITLE_PAID','TITLE_CANCELED')),
 description text not null, metadata jsonb not null default '{}'::jsonb, actor_user_id uuid not null references auth.users(id), actor_name text not null, created_at timestamptz not null default now(), unique(organization_id,id)
);
create index arteflow_fin_recv_org_status_due_idx on public.arteflow_financial_receivables(organization_id,status,due_date);
create index arteflow_fin_pay_org_status_due_idx on public.arteflow_financial_payables(organization_id,status,due_date);
create index arteflow_fin_set_recv_idx on public.arteflow_financial_settlements(organization_id,receivable_id,settled_at);
create index arteflow_fin_set_pay_idx on public.arteflow_financial_settlements(organization_id,payable_id,settled_at);
create index arteflow_fin_events_entity_idx on public.arteflow_financial_events(organization_id,entity_type,entity_id,created_at);
do $$ declare t text; begin foreach t in array array['arteflow_financial_receivables','arteflow_financial_payables','arteflow_financial_settlements','arteflow_financial_events'] loop execute format('alter table public.%I enable row level security',t); execute format('create policy %I on public.%I for select to authenticated using (private.arteflow_has_permission(organization_id,''arteflow.finance.view''))',t||'_select',t); execute format('revoke all on public.%I from public,anon,authenticated',t); execute format('grant select on public.%I to authenticated',t); end loop; end $$;

create or replace function private.arteflow_require_finance(p_org uuid,p_manage boolean default false) returns void language plpgsql security definer set search_path='' as $$ begin if (select auth.uid()) is null or not private.arteflow_has_permission(p_org,case when p_manage then 'arteflow.finance.manage' else 'arteflow.finance.view' end) then raise exception 'FINANCE_%_DENIED',case when p_manage then 'MANAGE' else 'VIEW' end using errcode='42501'; end if; end $$;
revoke all on function private.arteflow_require_finance(uuid,boolean) from public,anon,authenticated;
create or replace function private.arteflow_finance_actor_name() returns text language sql stable security definer set search_path='' as $$ select coalesce(u.raw_user_meta_data->>'name',u.email,'Usuário') from auth.users u where u.id=(select auth.uid()) $$;
revoke all on function private.arteflow_finance_actor_name() from public,anon,authenticated;

create or replace function private.arteflow_create_receivable_for_order(p_org uuid,p_order uuid) returns uuid language plpgsql security definer set search_path='' as $$ declare o public.arteflow_orders%rowtype; v uuid; begin select * into o from public.arteflow_orders where organization_id=p_org and id=p_order and status<>'CANCELLED' and total_amount_cents>0; if not found then return null; end if; insert into public.arteflow_financial_receivables(organization_id,order_id,order_number,customer_id,customer_name,description,amount_cents,due_date,created_by) values(p_org,o.id,o.order_number,o.customer_snapshot_id,o.customer_name,'Pedido '||o.order_number,o.total_amount_cents,o.delivery_date::date,o.created_by) on conflict(organization_id,order_id) do update set order_id=excluded.order_id returning id into v; insert into public.arteflow_financial_events(organization_id,entity_type,entity_id,event_type,description,actor_user_id,actor_name) select p_org,'RECEIVABLE',v,'RECEIVABLE_CREATED','Conta criada para '||o.order_number,o.created_by,coalesce((select raw_user_meta_data->>'name' from auth.users where id=o.created_by),'Sistema') where not exists(select 1 from public.arteflow_financial_events where organization_id=p_org and entity_type='RECEIVABLE' and entity_id=v and event_type='RECEIVABLE_CREATED'); return v; end $$;
revoke all on function private.arteflow_create_receivable_for_order(uuid,uuid) from public,anon,authenticated;
create or replace function private.arteflow_create_payable_for_purchase(p_org uuid,p_order uuid) returns uuid language plpgsql security definer set search_path='' as $$ declare o public.arteflow_purchase_orders%rowtype; v uuid; begin select * into o from public.arteflow_purchase_orders where organization_id=p_org and id=p_order and status in('ISSUED','PARTIALLY_RECEIVED','RECEIVED') and total_cents>0; if not found then return null; end if; insert into public.arteflow_financial_payables(organization_id,purchase_order_id,purchase_order_number,supplier_id,supplier_name,description,amount_cents,due_date,created_by) values(p_org,o.id,o.order_number,o.supplier_id,coalesce(o.supplier_snapshot->>'tradeName','Fornecedor'),'Pedido de compra '||o.order_number,o.total_cents,coalesce(o.expected_at::date,current_date),o.created_by) on conflict(organization_id,purchase_order_id) do update set purchase_order_id=excluded.purchase_order_id returning id into v; insert into public.arteflow_financial_events(organization_id,entity_type,entity_id,event_type,description,actor_user_id,actor_name) select p_org,'PAYABLE',v,'PAYABLE_CREATED','Conta criada para '||o.order_number,o.created_by,o.actor_name where not exists(select 1 from public.arteflow_financial_events where organization_id=p_org and entity_type='PAYABLE' and entity_id=v and event_type='PAYABLE_CREATED'); return v; end $$;
revoke all on function private.arteflow_create_payable_for_purchase(uuid,uuid) from public,anon,authenticated;
create or replace function private.arteflow_finance_order_trigger() returns trigger language plpgsql security definer set search_path='' as $$ begin perform private.arteflow_create_receivable_for_order(new.organization_id,new.id); return new; end $$;
create trigger arteflow_order_financial_after after insert or update of status on public.arteflow_orders for each row execute function private.arteflow_finance_order_trigger();
create or replace function private.arteflow_finance_purchase_trigger() returns trigger language plpgsql security definer set search_path='' as $$ begin perform private.arteflow_create_payable_for_purchase(new.organization_id,new.id); return new; end $$;
create trigger arteflow_purchase_financial_after after insert or update of status on public.arteflow_purchase_orders for each row execute function private.arteflow_finance_purchase_trigger();
revoke all on function private.arteflow_finance_order_trigger() from public,anon,authenticated;
revoke all on function private.arteflow_finance_purchase_trigger() from public,anon,authenticated;

create or replace function public.arteflow_ensure_receivable_for_order(p_organization_id uuid,p_order_id uuid) returns uuid language plpgsql security definer set search_path='' as $$ begin perform private.arteflow_require_finance(p_organization_id,true); return private.arteflow_create_receivable_for_order(p_organization_id,p_order_id); end $$;
create or replace function public.arteflow_create_receivable(p_organization_id uuid,p_description text,p_amount_cents bigint,p_due_date date,p_customer_name text) returns uuid language plpgsql security definer set search_path='' as $$ declare v uuid; begin perform private.arteflow_require_finance(p_organization_id,true); insert into public.arteflow_financial_receivables(organization_id,customer_name,description,amount_cents,due_date,created_by) values(p_organization_id,btrim(p_customer_name),btrim(p_description),p_amount_cents,p_due_date,(select auth.uid())) returning id into v; insert into public.arteflow_financial_events(organization_id,entity_type,entity_id,event_type,description,actor_user_id,actor_name) values(p_organization_id,'RECEIVABLE',v,'RECEIVABLE_CREATED','Conta a receber criada',(select auth.uid()),private.arteflow_finance_actor_name()); return v; end $$;
create or replace function public.arteflow_create_payable(p_organization_id uuid,p_description text,p_amount_cents bigint,p_due_date date,p_supplier_name text) returns uuid language plpgsql security definer set search_path='' as $$ declare v uuid; begin perform private.arteflow_require_finance(p_organization_id,true); insert into public.arteflow_financial_payables(organization_id,supplier_name,description,amount_cents,due_date,created_by) values(p_organization_id,btrim(p_supplier_name),btrim(p_description),p_amount_cents,p_due_date,(select auth.uid())) returning id into v; insert into public.arteflow_financial_events(organization_id,entity_type,entity_id,event_type,description,actor_user_id,actor_name) values(p_organization_id,'PAYABLE',v,'PAYABLE_CREATED','Conta a pagar criada',(select auth.uid()),private.arteflow_finance_actor_name()); return v; end $$;

create or replace function public.arteflow_settle_receivable(p_organization_id uuid,p_receivable_id uuid,p_amount_cents bigint,p_settled_at timestamptz,p_method text,p_notes text,p_idempotency_key text) returns uuid language plpgsql security definer set search_path='' as $$ declare a public.arteflow_financial_receivables%rowtype; v uuid; v_status text; v_actor text; j record; begin perform private.arteflow_require_finance(p_organization_id,true); if nullif(btrim(p_idempotency_key),'') is null then raise exception 'IDEMPOTENCY_KEY_REQUIRED'; end if; select id into v from public.arteflow_financial_settlements where organization_id=p_organization_id and idempotency_key=p_idempotency_key; if found then return v; end if; select * into a from public.arteflow_financial_receivables where organization_id=p_organization_id and id=p_receivable_id for update; if not found then raise exception 'RECEIVABLE_NOT_FOUND'; end if; if a.status='CANCELED' then raise exception 'TITLE_CANCELED'; end if; if p_amount_cents<=0 or p_amount_cents>a.amount_cents-a.paid_amount_cents then raise exception 'PAYMENT_EXCEEDS_REMAINING'; end if; v_status:=case when a.paid_amount_cents+p_amount_cents=a.amount_cents then 'PAID' else 'PARTIALLY_PAID' end; v_actor:=private.arteflow_finance_actor_name(); insert into public.arteflow_financial_settlements(organization_id,receivable_id,amount_cents,settled_at,method,notes,idempotency_key,created_by,actor_name) values(p_organization_id,a.id,p_amount_cents,p_settled_at,p_method,nullif(btrim(p_notes),''),p_idempotency_key,(select auth.uid()),v_actor) returning id into v; update public.arteflow_financial_receivables set paid_amount_cents=paid_amount_cents+p_amount_cents,status=v_status,version=version+1,updated_at=now() where id=a.id; insert into public.arteflow_financial_events(organization_id,entity_type,entity_id,event_type,description,metadata,actor_user_id,actor_name) values(p_organization_id,'RECEIVABLE',a.id,case when v_status='PAID' then 'TITLE_PAID' else 'PARTIAL_SETTLEMENT' end,'Baixa registrada',jsonb_build_object('settlementId',v,'amountCents',p_amount_cents),(select auth.uid()),v_actor); for j in select id,financial_gate from public.arteflow_production_jobs where organization_id=p_organization_id and order_id=a.order_id for update loop update public.arteflow_production_jobs set financial_gate=case when v_status='PAID' then 'RELEASED' else 'PAYMENT_PENDING' end,version=version+1,updated_at=now() where id=j.id; insert into public.arteflow_production_job_events(organization_id,job_id,actor_user_id,actor_name,event_type,from_value,to_value,description) values(p_organization_id,j.id,(select auth.uid()),v_actor,'FINANCIAL_GATE_CHANGED',j.financial_gate,case when v_status='PAID' then 'RELEASED' else 'PAYMENT_PENDING' end,'Gate financeiro atualizado pela baixa'); end loop; return v; exception when unique_violation then select id into v from public.arteflow_financial_settlements where organization_id=p_organization_id and idempotency_key=p_idempotency_key; if found then return v; end if; raise; end $$;
create or replace function public.arteflow_settle_payable(p_organization_id uuid,p_payable_id uuid,p_amount_cents bigint,p_settled_at timestamptz,p_method text,p_notes text,p_idempotency_key text) returns uuid language plpgsql security definer set search_path='' as $$ declare a public.arteflow_financial_payables%rowtype; v uuid; v_status text; begin perform private.arteflow_require_finance(p_organization_id,true); select id into v from public.arteflow_financial_settlements where organization_id=p_organization_id and idempotency_key=p_idempotency_key; if found then return v; end if; select * into a from public.arteflow_financial_payables where organization_id=p_organization_id and id=p_payable_id for update; if not found then raise exception 'PAYABLE_NOT_FOUND'; end if; if a.status='CANCELED' then raise exception 'TITLE_CANCELED'; end if; if p_amount_cents<=0 or p_amount_cents>a.amount_cents-a.paid_amount_cents then raise exception 'PAYMENT_EXCEEDS_REMAINING'; end if; v_status:=case when a.paid_amount_cents+p_amount_cents=a.amount_cents then 'PAID' else 'PARTIALLY_PAID' end; insert into public.arteflow_financial_settlements(organization_id,payable_id,amount_cents,settled_at,method,notes,idempotency_key,created_by,actor_name) values(p_organization_id,a.id,p_amount_cents,p_settled_at,p_method,nullif(btrim(p_notes),''),p_idempotency_key,(select auth.uid()),private.arteflow_finance_actor_name()) returning id into v; update public.arteflow_financial_payables set paid_amount_cents=paid_amount_cents+p_amount_cents,status=v_status,version=version+1,updated_at=now() where id=a.id; insert into public.arteflow_financial_events(organization_id,entity_type,entity_id,event_type,description,metadata,actor_user_id,actor_name) values(p_organization_id,'PAYABLE',a.id,case when v_status='PAID' then 'TITLE_PAID' else 'PARTIAL_SETTLEMENT' end,'Baixa registrada',jsonb_build_object('settlementId',v,'amountCents',p_amount_cents),(select auth.uid()),private.arteflow_finance_actor_name()); return v; end $$;
create or replace function public.arteflow_cancel_financial_title(p_organization_id uuid,p_title_type text,p_title_id uuid) returns uuid language plpgsql security definer set search_path='' as $$ declare v int; begin perform private.arteflow_require_finance(p_organization_id,true); if p_title_type='RECEIVABLE' then update public.arteflow_financial_receivables set status='CANCELED',version=version+1,updated_at=now() where organization_id=p_organization_id and id=p_title_id and paid_amount_cents=0 and status='OPEN'; get diagnostics v=row_count; elsif p_title_type='PAYABLE' then update public.arteflow_financial_payables set status='CANCELED',version=version+1,updated_at=now() where organization_id=p_organization_id and id=p_title_id and paid_amount_cents=0 and status='OPEN'; get diagnostics v=row_count; else raise exception 'INVALID_TITLE_TYPE'; end if; if v=0 then raise exception 'TITLE_NOT_CANCELLABLE'; end if; insert into public.arteflow_financial_events(organization_id,entity_type,entity_id,event_type,description,actor_user_id,actor_name) values(p_organization_id,p_title_type,p_title_id,'TITLE_CANCELED','Título cancelado',(select auth.uid()),private.arteflow_finance_actor_name()); return p_title_id; end $$;

alter table public.arteflow_financial_settlements add constraint arteflow_financial_settlements_idempotency_nonempty check (btrim(idempotency_key) <> '');

insert into public.arteflow_financial_receivables(organization_id,order_id,order_number,customer_id,customer_name,description,amount_cents,due_date,created_by) select o.organization_id,o.id,o.order_number,o.customer_snapshot_id,o.customer_name,'Pedido '||o.order_number,o.total_amount_cents,o.delivery_date::date,o.created_by from public.arteflow_orders o where o.status<>'CANCELLED' and o.total_amount_cents>0 on conflict(organization_id,order_id) do nothing;
insert into public.arteflow_financial_payables(organization_id,purchase_order_id,purchase_order_number,supplier_id,supplier_name,description,amount_cents,due_date,created_by) select o.organization_id,o.id,o.order_number,o.supplier_id,coalesce(o.supplier_snapshot->>'tradeName','Fornecedor'),'Pedido de compra '||o.order_number,o.total_cents,coalesce(o.expected_at::date,current_date),o.created_by from public.arteflow_purchase_orders o where o.status in('ISSUED','PARTIALLY_RECEIVED','RECEIVED') and o.total_cents>0 on conflict(organization_id,purchase_order_id) do nothing;
do $$ declare f record; begin for f in select p.oid::regprocedure sig from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname like 'arteflow_%financial%' or (n.nspname='public' and p.proname like 'arteflow_%receivable%') or (n.nspname='public' and p.proname like 'arteflow_%payable%') loop execute 'revoke all on function '||f.sig||' from public,anon'; execute 'grant execute on function '||f.sig||' to authenticated'; end loop; end $$;
